from functools import wraps

def validate_input(value: str) -> bool:
    return len(value) > 0

def validated(rules: dict):
    """验证装饰器，根据规则验证方法参数"""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            # 获取方法的验证规则
            method_rules = rules.get(func.__name__, {})

            # 验证位置参数
            for idx, arg in enumerate(args):
                param_name = method_rules.get('args', {}).get(idx)
                if param_name and param_name in method_rules.get('required', []):
                    if isinstance(arg, str) and not validate_input(arg):
                        raise ValueError(f"参数 '{param_name}' 验证失败: 不能为空")
                    if isinstance(arg, dict) and method_rules.get('validate_dict', False):
                        if not arg:
                            raise ValueError(f"参数 '{param_name}' 验证失败: 字典不能为空")

            # 验证关键字参数
            for key, value in kwargs.items():
                if key in method_rules.get('required', []):
                    if isinstance(value, str) and not validate_input(value):
                        raise ValueError(f"参数 '{key}' 验证失败: 不能为空")
                    if isinstance(value, dict) and method_rules.get('validate_dict', False):
                        if not value:
                            raise ValueError(f"参数 '{key}' 验证失败: 字典不能为空")

            return func(self, *args, **kwargs)
        return wrapper
    return decorator


class DataHandler:
    # 类级别的验证规则配置
    VALIDATION_RULES = {
        'transform': {
            'required': ['func'],
            'args': {0: 'func'},
            'validate_dict': False
        },
        'save': {
            'required': ['path'],
            'args': {0: 'path'},
            'validate_dict': False
        },
        'load': {
            'required': [],
            'args': {},
            'validate_dict': False
        },
        'process': {
            'required': ['data'],
            'args': {0: 'data'},
            'validate_dict': True
        }
    }

    def __init__(self, source: str):
        if not validate_input(source):
            raise ValueError("source 参数不能为空")
        self.source = source
        self.data = {}
        self._validation_rules = self.VALIDATION_RULES.copy()

    @validated(VALIDATION_RULES)
    def load(self) -> bool:
        """加载数据"""
        return True

    @validated(VALIDATION_RULES)
    def transform(self, func: Callable) -> dict:
        """转换数据"""
        if func is None:
            raise ValueError("func 参数不能为空")
        return {k: func(v) for k, v in self.data.items()}

    @validated(VALIDATION_RULES)
    def save(self, path: str) -> bool:
        """保存数据"""
        return True

    @validated(VALIDATION_RULES)
    def process(self, data: dict) -> dict:
        """处理数据"""
        result = {}
        for key, value in data.items():
            result[key] = str(value).upper()
        return result

    def get_validation_rule(self, method_name: str) -> dict:
        """获取特定方法的验证规则"""
        return self._validation_rules.get(method_name, {})

    def update_validation_rule(self, method_name: str, rules: dict):
        """更新特定方法的验证规则"""
        if method_name in self._validation_rules:
            self._validation_rules[method_name].update(rules)


