from typing import Optional, Any, List, Dict, Union, Callable
from dataclasses import dataclass, field
import re


class ValidationError(Exception):
    """自定义验证错误异常"""

    def __init__(self, message: str, field: str = None, errors: List[dict] = None):
        self.message = message
        self.field = field
        self.errors = errors or []
        super().__init__(self.message)

    def __str__(self):
        if self.errors:
            return f"{self.message}: {self.errors}"
        return self.message


@dataclass
class ValidationResult:
    """验证结果对象"""
    is_valid: bool = True
    errors: List[Dict[str, str]] = field(default_factory=list)
    data: Any = None

    def add_error(self, field: str, message: str):
        self.is_valid = False
        self.errors.append({"field": field, "message": message})

    def get_error_messages(self) -> List[str]:
        """获取所有错误消息"""
        return [f"{err['field']}: {err['message']}" for err in self.errors]

    def __bool__(self):
        return self.is_valid

    def __repr__(self):
        return f"ValidationResult(is_valid={self.is_valid}, errors={self.errors})"


def validate_input(
    data: Any,
    required_fields: Optional[List[str]] = None,
    optional_fields: Optional[List[str]] = None,
    field_types: Optional[Dict[str, type]] = None,
    field_patterns: Optional[Dict[str, str]] = None,
    field_min_length: Optional[Dict[str, int]] = None,
    field_max_length: Optional[Dict[str, int]] = None,
    field_custom_validators: Optional[Dict[str, Callable]] = None,
    allow_extra_fields: bool = True,
    strict: bool = False,
    raise_on_error: bool = False
) -> ValidationResult:
    """
    通用输入验证函数

    参数:
        data: 要验证的输入数据（dict 或其他类型）
        required_fields: 必填字段列表
        optional_fields: 可选字段列表
        field_types: 字段类型映射 {字段名: 期望类型}
        field_patterns: 字段正则表达式模式 {字段名: 正则表达式字符串}
        field_min_length: 字段最小长度限制 {字段名: 最小长度}
        field_max_length: 字段最大长度限制 {字段名: 最大长度}
        field_custom_validators: 自定义验证器 {字段名: callable}
        allow_extra_fields: 是否允许额外字段（不在required和optional中）
        strict: 严格模式（不允许额外字段且required_fields不能为空）
        raise_on_error: 验证失败时是否抛出 ValidationError 异常

    返回:
        ValidationResult: 验证结果对象
    """
    result = ValidationResult()

    # 初始化参数
    required_fields = required_fields or []
    optional_fields = optional_fields or []
    field_types = field_types or {}
    field_patterns = field_patterns or {}
    field_min_length = field_min_length or {}
    field_max_length = field_max_length or {}
    field_custom_validators = field_custom_validators or {}

    # 严格模式设置
    if strict:
        allow_extra_fields = False
        if not required_fields:
            required_fields = list(data.keys()) if isinstance(data, dict) else []

    # 检查数据类型
    if not isinstance(data, dict):
        result.add_error("_root", "Input data must be a dictionary")
        if raise_on_error:
            raise ValidationError("Input data must be a dictionary", errors=result.errors)
        return result

    # 合并所有有效字段
    valid_fields = set(required_fields) | set(optional_fields)

    # 检查额外字段
    if not allow_extra_fields:
        extra_fields = set(data.keys()) - valid_fields
        if extra_fields:
            for field_name in extra_fields:
                result.add_error(field_name, f"Extra field not allowed: {field_name}")

    # 检查必填字段是否存在
    for field_name in required_fields:
        if field_name not in data:
            result.add_error(field_name, "Required field is missing")
        elif data[field_name] is None:
            result.add_error(field_name, "Required field cannot be None")

    # 验证所有字段
    for field_name, value in data.items():
        # 检查字段是否在白名单中
        if not allow_extra_fields and field_name not in valid_fields:
            continue

        # 类型检查
        if field_name in field_types:
            expected_type = field_types[field_name]
            if not isinstance(value, expected_type):
                result.add_error(
                    field_name,
                    f"Expected type {expected_type.__name__}, got {type(value).__name__}"
                )
                continue  # 类型错误时跳过后续检查

        # 空值检查（对于已存在的字段）
        if value is None:
            if field_name in required_fields:
                result.add_error(field_name, "Field cannot be None")
            continue

        # 字符串类型验证
        if isinstance(value, str):
            # 长度限制
            if field_name in field_min_length:
                min_len = field_min_length[field_name]
                if len(value) < min_len:
                    result.add_error(field_name, f"Length must be at least {min_len}")

            if field_name in field_max_length:
                max_len = field_max_length[field_name]
                if len(value) > max_len:
                    result.add_error(field_name, f"Length must not exceed {max_len}")

            # 正则表达式匹配
            if field_name in field_patterns:
                pattern = field_patterns[field_name]
                if not re.match(pattern, value):
                    result.add_error(field_name, f"Value does not match pattern: {pattern}")

        # 列表类型验证
        if isinstance(value, list):
            if field_name in field_min_length:
                min_len = field_min_length[field_name]
                if len(value) < min_len:
                    result.add_error(field_name, f"List must contain at least {min_len} items")

            if field_name in field_max_length:
                max_len = field_max_length[field_name]
                if len(value) > max_len:
                    result.add_error(field_name, f"List must not exceed {max_len} items")

        # 字典类型验证
        if isinstance(value, dict):
            if field_name in field_min_length:
                min_len = field_min_length[field_name]
                if len(value) < min_len:
                    result.add_error(field_name, f"Dict must contain at least {min_len} keys")

            if field_name in field_max_length:
                max_len = field_max_length[field_name]
                if len(value) > max_len:
                    result.add_error(field_name, f"Dict must not exceed {max_len} keys")

        # 自定义验证器
        if field_name in field_custom_validators:
            validator = field_custom_validators[field_name]
            try:
                if not validator(value):
                    result.add_error(field_name, "Custom validation failed")
            except Exception as e:
                result.add_error(field_name, f"Custom validation error: {str(e)}")

    # 设置结果数据
    result.data = data

    # 抛出异常
    if raise_on_error and not result.is_valid:
        raise ValidationError(
            "Validation failed",
            errors=result.errors
        )

    return result


